export * from "./schema";
import type { Config } from "drizzle-kit";

export default {
  schema: "./src/server/db/schema/index.ts",
  out: "./drizzle",
  dialect: "sqlite",
  dbCredentials: {
    url: "./data/taskflow.db",
  },
  strict: true,
  verbose: true,
} satisfies Config;
