import type {
  IsoTimestamp,
  MilestoneId,
  ProjectId,
  TenantScoped,
  Timestamps,
} from "./common";

/** A named target inside one project. Open from creation until it is closed. */
export interface Milestone extends Timestamps, TenantScoped {
  readonly id: MilestoneId;
  readonly projectId: ProjectId;
  readonly name: string;
  readonly targetDate: IsoTimestamp | null;
  readonly closedAt: IsoTimestamp | null;
}

/** Counts over a milestone's live issues. `open` excludes done and canceled. */
export interface MilestoneProgress {
  readonly total: number;
  readonly open: number;
  readonly closed: number;
}

export interface MilestoneWithProgress {
  readonly milestone: Milestone;
  readonly progress: MilestoneProgress;
  readonly overdue: boolean;
}
EOF
cat > src/lib/milestones.ts <<'EOF'
/**
 * Milestone rules that do not need the database: the state-conflict error the
 * service layer throws, and the name comparison that makes names unique.
 */

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

/**
 * Raised when a milestone is in the wrong state for the operation, or a
 * project-level limit or uniqueness rule would be broken. Maps to `conflict`.
 */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: MilestoneStateReason) {
    super(MILESTONE_STATE_MESSAGES[reason]);
    this.name = "MilestoneStateError";
  }
}

const MILESTONE_STATE_MESSAGES: Readonly<Record<MilestoneStateReason, string>> = {
  closed: "The milestone is closed.",
  already_open: "The milestone is already open.",
  too_many_open: "The project has too many open milestones.",
  name_taken: "A milestone with that name already exists in this project.",
};

/** Names compare without regard to letter case or surrounding spaces. */
export function normalizeMilestoneName(name: string): string {
  return name.trim().toLowerCase();
}
EOF

