cat > src/server/repositories/milestone-repository.ts <<'EOF'
/**
 * Milestone rows and their progress counts. Progress is one grouped query per
 * project, so its cost does not grow with the number of issues in it.
 *
 * Must call (do not reimplement): orgPredicate, toMilestone, CLOSED_ISSUE_STATUSES
 */
import { and, asc, count, eq, isNotNull, isNull, notInArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toMilestone } from "./_mappers";
import type { UpdateMilestoneInput } from "@/schemas/milestone";
import type {
  IsoTimestamp,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/**
 * Every milestone of a project, open ones first, then by target date (earliest
 * first, undated last), ties by creation, oldest first.
 */
export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .orderBy(
      sql`${milestones.closedAt} IS NOT NULL`,
      sql`${milestones.targetDate} IS NULL`,
      asc(milestones.targetDate),
      asc(milestones.createdAt),
      asc(milestones.id),
    )
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/** Live issue counts per milestone of one project; milestones with none are absent. */
export async function milestoneProgressForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ReadonlyMap<MilestoneId, MilestoneProgress>> {
  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        isNotNull(issues.milestoneId),
        isNull(issues.archivedAt),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  const progress = new Map<MilestoneId, MilestoneProgress>();
  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const id = row.milestoneId as MilestoneId;
    const previous = progress.get(id) ?? { total: 0, open: 0, closed: 0 };
    const isClosed = (CLOSED_ISSUE_STATUSES as readonly string[]).includes(
      row.status,
    );
    progress.set(id, {
      total: previous.total + row.value,
      open: previous.open + (isClosed ? 0 : row.value),
      closed: previous.closed + (isClosed ? row.value : 0),
    });
  }
  return progress;
}

export async function insertMilestone(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  targetDate: IsoTimestamp | null,
): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId,
      projectId,
      name,
      targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toMilestone(row);
}

export async function updateMilestone(
  input: UpdateMilestoneInput,
  name: string | undefined,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(name === undefined ? {} : { name }),
      ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(milestones.orgId, input.orgId),
        eq(milestones.id, input.milestoneId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${input.milestoneId} not found`);
  return toMilestone(row);
}

export async function setMilestoneClosedAt(
  orgId: OrgId,
  milestoneId: MilestoneId,
  closedAt: IsoTimestamp | null,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Closes a milestone and moves its open live issues in one transaction. The
 * move is a single UPDATE selected by predicate, so it does not depend on how
 * many issues there are. Returns the ids that moved.
 */
export async function closeMilestoneAndMoveOpenIssues(
  orgId: OrgId,
  milestoneId: MilestoneId,
  moveTo: MilestoneId | null,
  closedAt: IsoTimestamp,
): Promise<{ milestone: Milestone; movedIssueIds: readonly string[] }> {
  return getDb().transaction((tx) => {
    const moved = tx
      .update(issues)
      .set({ milestoneId: moveTo, updatedAt: closedAt })
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.milestoneId, milestoneId),
          isNull(issues.archivedAt),
          notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
        ),
      )
      .returning({ id: issues.id })
      .all();

    const row = tx
      .update(milestones)
      .set({ closedAt, updatedAt: closedAt })
      .where(
        and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
      )
      .returning()
      .get();

    if (!row) throw new Error(`Milestone ${milestoneId} not found`);
    return {
      milestone: toMilestone(row),
      movedIssueIds: moved.map((issue) => issue.id),
    };
  });
}
EOF
