/**
 * Milestone lifecycle inside a project: creation with unique names and an open-milestone cap, rename and retarget, closing (which moves open issues), reopening, and the progress reads the project views use.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, emit, normalizeMilestoneName, requireFound
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError, normalizeMilestoneName } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { toIsoTimestamp } from "@/types/common";
import {
  actorEnvelope,
  NotFoundError,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Milestone, MilestoneProgress, MilestoneWithProgress } from "@/types/milestone";
import type { Project } from "@/types/project";

const NO_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const project = await requireWritableProject(actor, input.orgId, input.projectId);

  const name = input.name.trim();
  assertNameFree(
    await milestoneRepo.listMilestonesForProject(input.orgId, project.id),
    name,
    null,
  );
  await assertOpenCapacity(input.orgId, project.id);

  const milestone = await milestoneRepo.insertMilestone(
    input.orgId,
    project.id,
    name,
    input.targetDate,
  );

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: project.id,
  });

  return milestone;
}

/** Renaming and retargeting are allowed on closed milestones too. */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const milestone = await requireMilestone(input.orgId, input.milestoneId);
  await requireWritableProject(actor, input.orgId, milestone.projectId);

  const name = input.name?.trim();
  if (name !== undefined) {
    assertNameFree(
      await milestoneRepo.listMilestonesForProject(input.orgId, milestone.projectId),
      name,
      milestone.id,
    );
  }

  return milestoneRepo.updateMilestone(input, name);
}

/**
 * Closing moves the open live issues to `moveOpenIssuesTo` (another open
 * milestone of the same project) or takes them out of any milestone. Closed and
 * archived issues stay where they are. Every check runs before anything is
 * written, so a refused close changes nothing and announces nothing.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);
  const milestone = await requireMilestone(input.orgId, input.milestoneId);
  await requireWritableProject(actor, input.orgId, milestone.projectId);

  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");

  const target =
    input.moveOpenIssuesTo === null
      ? null
      : await requireMoveTarget(input.orgId, milestone, input.moveOpenIssuesTo);

  const { milestone: closed, movedIssueIds } =
    await milestoneRepo.closeMilestoneAndMoveOpenIssues(
      input.orgId,
      milestone.id,
      target?.id ?? null,
      toIsoTimestamp(new Date()),
    );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: target?.id ?? null,
    movedIssueIds,
  });

  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);
  const milestone = await requireMilestone(orgId, milestoneId);
  await requireWritableProject(actor, orgId, milestone.projectId);

  if (milestone.closedAt === null) throw new MilestoneStateError("already_open");
  await assertOpenCapacity(orgId, milestone.projectId);

  const reopened = await milestoneRepo.setMilestoneClosedAt(orgId, milestone.id, null);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

/** Readable by anyone who may read the project, including once it is archived. */
export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);
  const project = await requireReadableProject(actor, orgId, projectId);

  const [all, progress] = await Promise.all([
    milestoneRepo.listMilestonesForProject(orgId, project.id),
    milestoneRepo.milestoneProgressForProject(orgId, project.id),
  ]);

  const now = Date.now();
  return sortMilestones(all).map((milestone) =>
    withProgress(milestone, progress.get(milestone.id) ?? NO_PROGRESS, now),
  );
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);
  const milestone = await requireMilestone(orgId, milestoneId);
  await requireReadableProject(actor, orgId, milestone.projectId);

  const progress = await milestoneRepo.milestoneProgressForProject(
    orgId,
    milestone.projectId,
  );

  return withProgress(milestone, progress.get(milestone.id) ?? NO_PROGRESS, Date.now());
}

/**
 * The rule for placing an issue into a milestone: the milestone must belong to
 * the issue's own project and must be open. Used at creation and on every move.
 */
export async function requireOpenMilestoneFor(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const milestone = await milestoneRepo.findMilestoneById(orgId, milestoneId);
  if (milestone === null || milestone.projectId !== projectId) {
    throw new NotFoundError("Milestone", milestoneId);
  }
  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");
  return milestone;
}

async function requireMilestone(orgId: OrgId, milestoneId: MilestoneId): Promise<Milestone> {
  return requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
}

/** The write gate for milestones: `project:update`, then the project must be live. */
async function requireWritableProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return project;
}

async function requireReadableProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));
  return project;
}

/** The target of a close: another open milestone of the same project. */
async function requireMoveTarget(
  orgId: OrgId,
  source: Milestone,
  targetId: MilestoneId,
): Promise<Milestone> {
  const target = await milestoneRepo.findMilestoneById(orgId, targetId);
  if (target === null || target.id === source.id || target.projectId !== source.projectId) {
    throw new NotFoundError("Milestone", targetId);
  }
  if (target.closedAt !== null) throw new MilestoneStateError("closed");
  return target;
}

/** Names are unique per project, closed milestones included. */
function assertNameFree(
  existing: readonly Milestone[],
  name: string,
  exceptId: MilestoneId | null,
): void {
  const wanted = normalizeMilestoneName(name);
  const taken = existing.some(
    (milestone) =>
      milestone.id !== exceptId && normalizeMilestoneName(milestone.name) === wanted,
  );
  if (taken) throw new MilestoneStateError("name_taken");
}

/** Creating or reopening needs room under the open-milestone cap. */
async function assertOpenCapacity(orgId: OrgId, projectId: ProjectId): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

/** Open before closed; then target date earliest first, undated last; then oldest first. */
function sortMilestones(milestones: readonly Milestone[]): readonly Milestone[] {
  return [...milestones].sort((a, b) => {
    const openFirst = Number(a.closedAt !== null) - Number(b.closedAt !== null);
    if (openFirst !== 0) return openFirst;

    if (a.targetDate === null || b.targetDate === null) {
      if (a.targetDate !== b.targetDate) return a.targetDate === null ? 1 : -1;
    } else {
      const byTarget = Date.parse(a.targetDate) - Date.parse(b.targetDate);
      if (byTarget !== 0) return byTarget;
    }

    if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
  });
}

function withProgress(
  milestone: Milestone,
  progress: MilestoneProgress,
  nowMs: number,
): MilestoneWithProgress {
  const overdue =
    milestone.closedAt === null &&
    milestone.targetDate !== null &&
    Date.parse(milestone.targetDate) < nowMs &&
    progress.open > 0;
  return { milestone, progress, overdue };
}
