import * as milestoneService from "@/server/services/milestone-service";
import * as notificationService from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId, IsoTimestamp, MilestoneId, OrgId } from "@/types/common";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

function createMilestone(tenant: Tenant, name: string, targetDate: IsoTimestamp | null = null) {
  return milestoneService.createMilestone(tenant.actors.member, {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    name,
    targetDate,
  });
}

function capture<K extends "milestone.closed" | "milestone.created" | "milestone.reopened">(
  type: K,
): { seen: TaskflowEventMap[K][]; off: Unsubscribe } {
  const seen: TaskflowEventMap[K][] = [];
  const off = subscribe(type, (payload) => {
    seen.push(payload);
  });
  return { seen, off };
}

describe("services/milestone-service", () => {
  it("refuses a name already used in the project, ignoring case and surrounding spaces, closed ones included", async () => {
    const tenant = await createTenant("ms-names", "growth");
    const first = await createMilestone(tenant, "Launch");

    await expect(createMilestone(tenant, "  launch ")).rejects.toMatchObject({
      reason: "name_taken",
    });

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: first.id,
      moveOpenIssuesTo: null,
    });
    await expect(createMilestone(tenant, "LAUNCH")).rejects.toBeInstanceOf(
      MilestoneStateError,
    );

    // The same name is fine in another project of another workspace.
    const other = await createTenant("ms-names-other", "growth");
    await expect(createMilestone(other, "Launch")).resolves.toMatchObject({ name: "Launch" });
  });

  it("caps open milestones per project; closed ones do not count", async () => {
    const tenant = await createTenant("ms-cap", "growth");
    const ids: MilestoneId[] = [];
    for (let i = 0; i < MAX_OPEN_MILESTONES_PER_PROJECT; i += 1) {
      ids.push((await createMilestone(tenant, `Cap ${i}`)).id);
    }

    await expect(createMilestone(tenant, "One too many")).rejects.toMatchObject({
      reason: "too_many_open",
    });

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: ids[0]!,
      moveOpenIssuesTo: null,
    });
    await expect(createMilestone(tenant, "Fits now")).resolves.toMatchObject({ name: "Fits now" });

    await expect(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, ids[0]!),
    ).rejects.toMatchObject({ reason: "too_many_open" });
  });

  it("moves open live issues on close, leaves closed ones, and alerts each assignee once but not the closer", async () => {
    const tenant = await createTenant("ms-close", "growth");
    const from = await createMilestone(tenant, "From");
    const to = await createMilestone(tenant, "To");

    const open = await issueService.createIssue(
      tenant.actors.member,
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "Still open", assigneeId: tenant.userIds.admin }), milestoneId: from.id },
    );
    const finished = await issueService.createIssue(
      tenant.actors.member,
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "Already done" }), milestoneId: from.id },
    );
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: finished.id,
      status: "done",
    });

    const closed = capture("milestone.closed");
    const result = await milestoneService.closeMilestone(tenant.actors.owner, {
      orgId: tenant.org.id,
      milestoneId: from.id,
      moveOpenIssuesTo: to.id,
    });

    expect(result.milestone.closedAt).not.toBeNull();
    expect(result.movedIssueIds).toEqual([open.id]);
    expect(closed.seen).toHaveLength(1);
    expect(closed.seen[0]).toMatchObject({ movedToMilestoneId: to.id, movedIssueIds: [open.id] });
    closed.off();

    const moved = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: open.id,
      milestoneId: to.id,
    });
    expect(moved.milestoneId).toBe(to.id);

