      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["issue_milestone_changed"],
      limit: 25,
      cursor: null,
    });
    expect(alerts.items).toHaveLength(1);

    const closerAlerts = await notificationService.listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      kind: ["issue_milestone_changed"],
      limit: 25,
      cursor: null,
    });
    expect(closerAlerts.items).toHaveLength(0);
  });

  it("reports progress and overdue over live issues, and never overdue without open issues", async () => {
    const tenant = await createTenant("ms-progress", "growth");
    const past = "2020-01-01T00:00:00.000Z" as IsoTimestamp;
    const late = await createMilestone(tenant, "Late", past);
    const issue = await issueService.createIssue(
      tenant.actors.member,
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "Late work" }), milestoneId: late.id },
    );

    const before = await milestoneService.getMilestone(tenant.actors.member, tenant.org.id, late.id);
