    expect(before.overdue).toBe(true);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "canceled",
    });
    const after = await milestoneService.getMilestone(tenant.actors.member, tenant.org.id, late.id);
    expect(after.progress).toEqual({ total: 1, open: 0, closed: 1 });
    expect(after.overdue).toBe(false);

    const listed = await milestoneService.listMilestones(tenant.actors.viewer, tenant.org.id, tenant.project.id);
    expect(listed.map((entry) => entry.milestone.name)).toEqual(["Late"]);
  });

