        milestoneId: source.id,
        moveOpenIssuesTo: source.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const elsewhere = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Elsewhere",
      slug: "elsewhere",
      key: "ELS",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const foreign = await milestoneService.createMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: elsewhere.id,
      name: "Foreign",
      targetDate: null,
    });

